-- Section: footer
INSERT INTO public.cms_content (key, content, updated_at)
VALUES ('footer', '{"logoUrl":"/darker-version-logo.png","logoDarkUrl":"/darker-version-logo.png","logoLightUrl":"/lighter-version-logo.png","tagline":"Delivering advanced RF, Microwave, and High-Rel electronic components from DC to 86 GHz for aerospace, defense, SATCOM, and telecommunications.","copyrightText":"© 2026 ICON ELECTROMATIC PRIVATE LIMITED. All rights reserved.","indiaOfficeName":"Icon Electromatic Pvt. Ltd. (India)","indiaAddress":"#303/2, 5th A Cross, HRBR Layout, III Block, Kalyan Nagar, Bengaluru – 560043","indiaPhone":"+91 80 2542 9452","indiaEmail":"salesiepl@iconelectromatic.com","singaporeOfficeName":"Icon Electromatic Singapore Pte Ltd","singaporeAddress":"204D Compassvale Drive #08-409, Singapore 544204","singaporeEmail":"IESing@iconelectromatic.com","usaOfficeName":"Icon Electromatic LLC (USA)","usaAddress":"15412 Meadow Vista Dr, Edmond, Oklahoma 73013, USA","usaPhone":"+1 405 593 5176","usaEmail":"salesiellc@iconelectromatic.com","linkedinUrl":"https://www.linkedin.com/company/icon-electromatic/","youtubeUrl":"#"}'::jsonb, timezone('utc'::text, now()))
