-- Section: home
INSERT INTO public.cms_content (key, content, updated_at)
VALUES ('home', '{"heroTitle":"ICON ELECTROMATIC turns complex high-frequency requirements into <span class=\"accent-red\" style=\"color: var(--logo-red);\">mission-ready hardware.</span>","heroSubtitle":"Delivering precision RF, microwave, and electronic components for defense, aerospace, SATCOM, and telecommunications.","heroBgVideo":"/icon-video.mp4","heroBgImage":"/images/hero-new-bg.png","ctaExploreText":"Explore Products","ctaExploreLink":"/products","ctaQuoteText":"Request a Quote","ctaQuoteLink":"/contact","stats":[{"id":"stat-1","value":"160+","label":"VERIFIED COMPONENTS"},{"id":"stat-2","value":"15","label":"OEM PARTNERS"},{"id":"stat-3","value":"100%","label":"ROHS & ISO 9001"}],"coreCapabilitiesTitle":"Core Capabilities","coreCapabilitiesSubtitle":"Engineered for extreme performance.","coreCapabilitiesLead":"From millimeter-wave defense radar to satellite ground infrastructure, we provide the verified hardware engineers depend on.","capabilities":[{"id":"cap-1","title":"RF & Microwave Active","desc":"High-linearity power amplifiers, ultra-low noise LNAs, active frequency mixers, and voltage-controlled oscillators.","linkText":"Explore Amplifiers →","linkUrl":"/products?category=amplifiers","icon":"fa-solid fa-wave-square"},{"id":"cap-2","title":"Passive & Waveguides","desc":"High-Q cavity bandpass filters, low-loss waveguide transitions, directional couplers, and coaxial terminations.","linkText":"Explore Filters →","linkUrl":"/products?category=filters","icon":"fa-solid fa-filter"},{"id":"cap-3","title":"Defense & Aerospace","desc":"Mil-Spec screening, extreme-temperature reliability, and radiation-tolerant solutions for tactical EW and SATCOM.","linkText":"Learn More →","linkUrl":"/about","icon":"fa-solid fa-shield-halved"},{"id":"cap-4","title":"Test & Measurement","desc":"Precision calibration adapters, armored low-loss RF test cables, and laboratory attenuator modules up to 86 GHz.","linkText":"Explore Solutions →","linkUrl":"/products?category=test-solutions","icon":"fa-solid fa-flask-vial"}],"popularTitle":"Popular Products & Components","popularLead":"High-frequency laminates, precision GaN semiconductors, 3D metamaterial optics, and microwave modules from our global OEM partners.","insightsTitle":"Insights","insightsSubtitle":"Latest Blogs","insightsLead":"Engineering articles, application notes, and microwave design breakthroughs from our technical team.","testimonialsTitle":"Trusted by Industry Leaders","testimonialsSubtitle":"What Defense, Space & Aerospace Engineers Say","testimonialsLead":"Engineered components and bespoke solutions deployed in mission-critical radar, satellite payloads, and defense communications across India and globally.","projectsTitle":"Featured Projects & Mission Milestones","projectsSubtitle":"Engineered for Extreme Environments","projectsLead":"Direct contributions to premier radar, aerospace, and high-frequency communication programs.","galleryTitle":"Hardware & Systems Showcase","gallerySubtitle":"High-Rel Components in Action","galleryLead":"Precision microwave active devices, passives, waveguide transitions, and advanced materials."}'::jsonb, timezone('utc'::text, now()))
ON CONFLICT (key) DO UPDATE SET
    content = EXCLUDED.content,
    updated_at = timezone('utc'::text, now());

-- Section: about
INSERT INTO public.cms_content (key, content, updated_at)
VALUES ('about', '{"heroEyebrow":"ABOUT ICON ELECTROMATIC","heroTitle":"About Us","heroLead":"Driven by decades of engineering expertise and global collaborations, Icon Electromatic Private Limited delivers advanced components and tailored solutions that transform design ambitions into reality.","badges":[{"id":"b-1","icon":"fa-solid fa-award","text":"Multi-Decade Pedigree","color":"#FDA4AF","bg":"rgba(225,29,72,0.08)","border":"rgba(225,29,72,0.25)"},{"id":"b-2","icon":"fa-solid fa-satellite","text":"Defense & Telecom Solutions","color":"#FCD34D","bg":"rgba(245,158,11,0.08)","border":"rgba(245,158,11,0.25)"},{"id":"b-3","icon":"fa-solid fa-globe","text":"Global OEM Representation","color":"#6EE7B7","bg":"rgba(16,185,129,0.08)","border":"rgba(16,185,129,0.25)"}],"coreCapabilitiesTitle":"Core Capabilities","coreCapabilitiesSubtitle":"Fulfillment partners for your electronic ambitions","companyDesc1":"Icon Electromatic was founded in 2009 in Bengaluru by engineers with decades of expertise in RF, Microwave, Semiconductors, and allied service industries. In 2020, the company transitioned into Icon Electromatic Private Limited and expanded its presence across India, Israel, Singapore, and the USA.","companyDesc2":"With deep experience in electronic research, development, and manufacturing ecosystems—spanning both public and private sectors—and strengthened by long-standing global partnerships, the company delivers more than advanced components. We also provide business consultancy and specialized RF design services to offer bespoke, high-performance solutions for its clients.","presentationLink":"/downloads/ICON_Corporate_Presentation_20Aug26.pptx","flyerLink":"/downloads/ICON_ELECTROMATIC_FLYER.pdf","highlightCards":[{"id":"hl-1","title":"Global Leader in RF & Electronic Solutions","desc":"Providing mission-critical components, assemblies, and custom microwave engineering for advanced applications.","icon":"fa-solid fa-tower-broadcast","color":"blue"},{"id":"hl-2","title":"Advanced Components, Consultancy & Bespoke Design Services","desc":"End-to-end design-in engineering, RF simulation review, and custom-tailored fulfillment for client success.","icon":"fa-solid fa-microchip","color":"red"}],"statsTitle":"Some Quick Facts","statsSubtitle":"The Numbers That Define Us","stats":[{"id":"s-1","target":"1500","suffix":"+","label":"Products","icon":"fa-solid fa-boxes-stacked","color":"red"},{"id":"s-2","target":"150","suffix":"+","label":"Years of combined experience","icon":"fa-solid fa-calendar-check","color":"blue"},{"id":"s-3","target":"15","suffix":"+","label":"Partners","icon":"fa-solid fa-handshake-angle","color":"red"}],"visionTitle":"Our Vision","visionDesc":"To be India’s foremost and most trusted source of essential electronics components for research, development, and manufacturing across both public and private sectors.","missionTitle":"Our Mission","missionDesc":"To introduce the world’s most cutting-edge technology solutions and components to India by forging strategic partnerships with global industry leaders, fostering indigenous product development and advancing “Make in India” initiatives.","journeyTitle":"Chronology","journeySubtitle":"Our Journey","journeyLead":"From our founding in Bengaluru in 2009 as RF & Microwave specialists to global operations spanning Singapore, the USA, and India — empowering mission-critical Aerospace, Defence, Space, and SATCOM programs.","infographicImage":"/images/timeline/icon-journey-infographic-full.png","milestones":[{"id":"m-1","year":"2009","title":"RF & Microwave Genesis","desc":"Established in Bengaluru, Karnataka by veteran RF & Microwave engineers focusing on defense electronics and aerospace components distribution.","image":"/images/timeline/timeline-2009-bengaluru.jpg","caption":"Genesis in Bengaluru, India","color":"cyan"},{"id":"m-2","year":"2018","title":"Singapore APAC Gateway","desc":"Incorporated Icon Electromatic Singapore Pte Ltd to anchor international supply chains and streamline East Asian semiconductor distribution.","image":"/images/timeline/timeline-2018-singapore.jpg","caption":"Regional Headquarters Singapore","color":"red"},{"id":"m-3","year":"May 2020","title":"USA Transatlantic Corridor","desc":"Expanded transatlantic footprint to the United States to collaborate directly with premier American microwave OEMs, ITAR suppliers, and global innovators.","image":"/images/timeline/timeline-2020-usa.jpg","caption":"US Operations, Oklahoma","color":"navy"},{"id":"m-4","year":"Nov 2020","title":"Incorporation in India","desc":"Transitioned and formally incorporated as Icon Electromatic Private Limited, scaling nationwide operations and advancing “Make in India” initiatives.","image":"/images/timeline/timeline-2020-india.jpg","caption":"Incorporation in India","color":"amber"}],"strategicDomainsTitle":"Strategic Application Domains","strategicDomainsSubtitle":"Where Our Technology Operates","strategicDomainsLead":"Delivering mission-critical electronic components, high-reliability assemblies, and custom microwave engineering across four strategic arenas.","domains":[{"id":"dom-1","title":"Aerospace & Defence","desc":"High-power GaN amplifiers, RF filters, waveguides, and radar subsystems for tactical airborne, naval, and ground-based defense platforms.","image":"/images/timeline/domain-aerospace-defence.jpg","tag":"Radar & EW Systems","icon":"fa-solid fa-jet-fighter"},{"id":"dom-2","title":"Hi-Rel Space","desc":"Spaceflight-qualified, radiation-tolerant microwave components and low-loss substrates engineered for orbital payloads and satellites.","image":"/images/timeline/domain-hirel-space.jpg","tag":"Space-Grade Qualified","icon":"fa-solid fa-satellite"},{"id":"dom-3","title":"6G & SATCOM","desc":"Ultra-wideband mmWave components, parabolic antenna feed networks, beamformers, and ground station transceivers.","image":"/images/timeline/domain-5g-satcom.jpg","tag":"Next-Gen Telecom","icon":"fa-solid fa-tower-cell"},{"id":"dom-4","title":"Homeland Security & Smart City","desc":"Perimeter intrusion detection systems (PIDS), tactical perimeter radar sensors, and smart city surveillance electronics.","image":"/images/timeline/domain-homeland-security.jpg","tag":"Intrusion & Radar","icon":"fa-solid fa-shield-halved"}],"pillars":[{"id":"pil-1","eyebrow":"GLOBAL ALLIANCES","title":"Global Partnerships","subtitle":"Advanced Technologies","desc":"Direct OEM partnerships with premier global innovators (Qorvo, Rogers, Tecdia, Mini-Circuits, and more), delivering verified authentic high-performance components to Indian industries.","image":"/images/timeline/pillar-global-partnerships.jpg","color":"blue"},{"id":"pil-2","eyebrow":"ENGINEERING EXPERTISE","title":"Bespoke Solutions","subtitle":"RF & Design Services","desc":"End-to-end design-in consultancy, specialized microwave simulation, prototyping, and custom RF assembly integration tailored precisely to mission specifications.","image":"/images/timeline/pillar-bespoke-solutions.jpg","color":"red"}],"whyUsTitle":"Our Advantage","whyUsSubtitle":"Why Us","whyUs":[{"id":"wu-1","number":"01","title":"We Help Customers Achieve Their Goals Without Compromise","desc":"Access an expanding portfolio of high-performance RF and Microwave components, mmWave, and Semiconductor components. Whether simple or highly complex, our solutions integrate seamlessly into your designs—saving time, reducing effort, and accelerating project success.","icon":"fa-solid fa-bullseye","color":"red"},{"id":"wu-2","number":"02","title":"Empowering You With Cutting-Edge Technology","desc":"From advanced ICs to mission-critical subsystems, we provide the technologies that unlock new possibilities. Our expertise helps you build smarter, faster, and more capable electronic systems across every application.","icon":"fa-solid fa-microchip","color":"blue"},{"id":"wu-3","number":"03","title":"Engineered Solutions Tailored to Your Needs","desc":"Combining engineering insight with best-in-class global products, we deliver solutions that balance innovation, performance, and reliability. Every recommendation is customised to your technical, commercial, and operational requirements.","icon":"fa-solid fa-gears","color":"red"},{"id":"wu-4","number":"04","title":"Access to Advanced Technology","desc":"Stay ahead with timely access to the latest RF, Microwave, mmWave, and Semiconductor innovations sourced from world-leading OEMs.","icon":"fa-solid fa-bolt","color":"blue"}]}'::jsonb, timezone('utc'::text, now()))
ON CONFLICT (key) DO UPDATE SET
    content = EXCLUDED.content,
    updated_at = timezone('utc'::text, now());

-- Section: services
INSERT INTO public.cms_content (key, content, updated_at)
VALUES ('services', '{"heroEyebrow":"CAPABILITIES & SERVICES","heroTitle":"Engineering Services & Global Representation","heroLead":"We represent major RF, Microwave, mmWave, Semiconductors, Components, Subsystems and Power supplies manufacturers around the world, providing unparalleled support to electronic designers, manufacturers, engineers and researchers.","badges":[{"id":"sb-1","icon":"fa-solid fa-handshake-angle","text":"Tier-1 Global Manufacturers Representation","color":"#93C5FD"},{"id":"sb-2","icon":"fa-solid fa-landmark","text":"Indian Govt Tender Portals (GeM & CPPP)","color":"#FDA4AF"},{"id":"sb-3","icon":"fa-solid fa-coins","text":"Global Multi-Currency Supply Logistics","color":"#E2E8F0"}],"items":[{"id":"srv-1","badge":"Tier-1 Global Representation","badgeColor":"blue","title":"Representation of Global Leaders","subtitle":"Global Distribution & Sourcing","desc":"We represent major RF and Microwave components, mmWave, Semiconductors, Components, Subsystems and Power supplies manufacturers around the world, providing unparalleled support to electronic designers, manufacturers, engineers and researchers.","ctaText":"Explore Represented Products","ctaLink":"/products","tags":["Direct OEM Warranty","Mil-Spec Screened","Traceable CoCs"],"slides":[{"image":"/images/hero-amplifier.jpg","caption":"RF Component Representation — Microwave Amplifier"},{"image":"/images/gan-power-chip.jpg","caption":"Active Antenna GaN MMIC Semiconductor"},{"image":"/images/rf-attenuator.jpg","caption":"Precision RF Attenuator Module"},{"image":"/images/rf-mixer.jpg","caption":"Microwave Frequency Mixer Subsystem"}]},{"id":"srv-2","badge":"End-to-End Fulfillment","badgeColor":"red","title":"Product Supply and Logistics","subtitle":"Supply Chain & Logistics","desc":"We offer end-to-end product supply and logistics support across global shipping locations and multiple currencies, with strong expertise in import and export operations. Our team is experienced across Indian Government tender portals, enabling seamless engagement in public-sector and strategic procurement.","desc2":"Supported by resources across geographies, we provide technical demonstrations, component selection, stack-up design verification, and application support throughout the design lifecycle.","ctaText":"Explore Logistics Options","ctaLink":"/contact","tags":["GeM & CPPP Portal Bidding","Customs & Duty Optimization","Multi-Currency Billing"],"slides":[{"image":"/images/defense-satcom.jpg","caption":"Product Supply and Logistics — Aerospace & Defense SATCOM"},{"image":"/images/rf-waveguide.jpg","caption":"Waveguide Assemblies & Hardware Logistics"},{"image":"/images/rf-microwave-pcb.jpg","caption":"High-Frequency Space-Grade PCB Supply"},{"image":"/images/dielectric-3d-lens.jpg","caption":"Specialized Dielectric Component Logistics"}]},{"id":"srv-3","badge":"Technical Simulation & Advisory","badgeColor":"blue","title":"Design Services","subtitle":"RF Engineering & Advisory","desc":"In order to help compliment our partners, we at Icon provide design services for designers and engineers looking for information and advice on our products. With our team available on call, we ensure that designers and engineers get all the information they need, when they need it.","ctaText":"Schedule Engineering Consultation","ctaLink":"/contact","tags":["On-Call Senior RF Engineers","Stack-Up & S-Parameter Verification","Prototype Tuning"],"slides":[{"image":"/images/rf-filter.webp","caption":"RF Design Services — Tunable Cavity Filter"},{"image":"/images/rf-laminate.jpg","caption":"High-Frequency Substrate Simulation & Stack-Up"},{"image":"/images/rf-filter.jpg","caption":"Custom Microwave Filter Design & Testing"},{"image":"/images/rf-switch.jpg","caption":"Solid-State RF Switch Prototype"}]},{"id":"srv-4","badge":"Enterprise Growth & Advisory","badgeColor":"red","title":"Business Consultancy","subtitle":"Strategic Partnerships","desc":"Our leadership collectively carries decades of professional expertise across various business domains. We further diversify this strength through meaningful partnerships with global leaders. We help organisations with Digital Transformation, next-generation Business Process Outsourcing, Make in India initiatives, and many more.","ctaText":"Initiate Business Discussion","ctaLink":"/contact","tags":["Make in India Strategy","Supply Chain Digitalization","Defense Offset Programs"],"slides":[{"image":"/images/rf-switch.jpg","caption":"Strategic Partnership Consultancy & Hi-Rel Technology"},{"image":"/images/rf-microwave-pcb.jpg","caption":"Make in India Manufacturing Support & Local FAB"},{"image":"/images/defense-satcom.jpg","caption":"Aerospace Program Consultancy"},{"image":"/images/gan-power-chip.jpg","caption":"Semiconductor Industry Modernization & BPO"}]}]}'::jsonb, timezone('utc'::text, now()))
ON CONFLICT (key) DO UPDATE SET
    content = EXCLUDED.content,
    updated_at = timezone('utc'::text, now());

-- Section: projects
INSERT INTO public.cms_content (key, content, updated_at)
VALUES ('projects', '{"heroTitle":"Featured Engineering Projects","heroSubtitle":"Mission-Ready Hardware Deployments","heroLead":"Delivering verified high-reliability RF and microwave subsystems for defense, space, SATCOM, and radar applications across India and international programs.","items":[{"id":"proj-1","title":"Multi-Band Radar Transceiver Subsystem","category":"Defense & Radar","clientSector":"Aerospace & Defense","desc":"High-power GaN amplifier modules, frequency synthesizers, and low-loss filter cascades integrated for multi-mission ground radar installations.","image":"/images/defense-satcom.jpg","date":"2025 - 2026","status":"Deployed","tags":["GaN SSPA","Cavity Filters","AESA"]},{"id":"proj-2","title":"Spaceflight Ku-Band Satellite Transponder","category":"SATCOM & Space","clientSector":"Satellite Ground & Payload","desc":"Radiation-tolerant microwave switches, dielectric metamaterial lenses, and precision ceramic capacitors screened for orbital payloads.","image":"/images/dielectric-3d-lens.jpg","date":"2025","status":"Flight Qualified","tags":["Mil-Spec","3D Dielectric","Ku-Band"]},{"id":"proj-3","title":"High-Frequency Substrate Stack-Up Optimization","category":"PCB Engineering","clientSector":"High-Speed Telecom","desc":"Precision simulation review and Rogers high-frequency copper clad laminate selection reducing insertion loss by 28% in 40 GHz test adapters.","image":"/images/rf-laminate.jpg","date":"2026","status":"Completed","tags":["Rogers RO4000","Impedance Match","Sub-40GHz"]},{"id":"proj-4","title":"Tactical Perimeter Intrusion Detection Array","category":"Homeland Security","clientSector":"Strategic Border Infrastructure","desc":"Micro-doppler radar sensors, high-rel RF switches, and temperature-stabilized RF assemblies deployed along sensitive perimeter installations.","image":"/images/rf-switch.jpg","date":"2025","status":"Active Service","tags":["PIDS","Radar Sensors","Ruggedized"]}]}'::jsonb, timezone('utc'::text, now()))
ON CONFLICT (key) DO UPDATE SET
    content = EXCLUDED.content,
    updated_at = timezone('utc'::text, now());

