INSERT INTO public.cms_content (key, content, updated_at)
VALUES ('gallery', '{"heroTitle":"Hardware & Facility Gallery","heroSubtitle":"High-Reliability Components & Systems","heroLead":"Visual showcase of microwave active modules, passives, waveguide transitions, precision substrates, and RF testing hardware.","items":[{"id":"gal-1","title":"High-Power GaN Microwave Amplifier","category":"Semiconductors","image":"/images/hero-amplifier.jpg","caption":"High-linearity solid-state pulsed power amplifier"},{"id":"gal-2","title":"Tunable Cavity Bandpass Filter","category":"Passives","image":"/images/rf-filter.webp","caption":"Sub-40 GHz ultra-low insertion loss filter module"},{"id":"gal-3","title":"Precision Microwave Waveguide Transition","category":"Passives","image":"/images/rf-waveguide.jpg","caption":"Mil-Spec low-VSWR rectangular waveguide assembly"},{"id":"gal-4","title":"Defense & SATCOM Earth Station Hardware","category":"Systems","image":"/images/defense-satcom.jpg","caption":"Ground terminal transceiver and feed assemblies"},{"id":"gal-5","title":"Active Phased Array GaN MMIC Die","category":"Semiconductors","image":"/images/gan-power-chip.jpg","caption":"Beamformer front-end module on ceramic carrier"},{"id":"gal-6","title":"High-Power PIN Diode RF Switch","category":"Modules","image":"/images/rf-switch.jpg","caption":"Fast-switching high-isolation multi-throw module"},{"id":"gal-7","title":"3D Printed Metamaterial Dielectric Lens","category":"Optics","image":"/images/dielectric-3d-lens.jpg","caption":"Fortify custom dielectric GRIN RF lens"},{"id":"gal-8","title":"Precision Laboratory Attenuator Module","category":"Test & Measurement","image":"/images/rf-attenuator.jpg","caption":"DC to 40 GHz calibrated step attenuator"}]}'::jsonb, timezone('utc'::text, now()))
