-- Section: testimonials
INSERT INTO public.cms_content (key, content, updated_at)
VALUES ('testimonials', '{"heroTitle":"Trusted by Industry Leaders","heroSubtitle":"Client & Engineer Endorsements","heroLead":"Feedback from senior scientists, microwave designers, and defense procurement leads who rely on Icon Electromatic.","items":[{"id":"test-1","name":"Dr. Vikram Nair","role":"Chief Scientist (Radar Systems)","company":"Defense Electronics Research Establishment","quote":"Icon Electromatic consistently delivers MIL-STD screened components with rock-solid traceability. Their engineering consultations on GaN SSPA modules cut months off our prototyping cycle.","stars":5,"avatar":"/images/oem-logos/Qorvo_logo_wb.png","industry":"Radar & Defense EW"},{"id":"test-2","name":"Siddharth Rao","role":"Head of RF Payload Engineering","company":"Aerospace & SATCOM Systems","quote":"From spaceflight-qualified dielectric substrates to custom cavity filters, Icon’s technical team in Bengaluru understands the nuances of high-frequency space transponders like few others.","stars":5,"avatar":"/images/oem-logos/Rogers_Logo_no_bg.png","industry":"Space Payloads & SATCOM"},{"id":"test-3","name":"Priya Swaminathan","role":"Senior Microwave Test Engineer","company":"Precision Instrumentation Labs","quote":"The accuracy and repeatability of their coaxial terminations, calibration adapters, and waveguide assemblies up to 67 GHz have made Icon Electromatic our primary partner for all test bench hardware.","stars":5,"avatar":"/images/oem-logos/mini-circuits-seeklogo.png","industry":"Test & Measurement"}]}'::jsonb, timezone('utc'::text, now()))
ON CONFLICT (key) DO UPDATE SET
    content = EXCLUDED.content,
    updated_at = timezone('utc'::text, now());

-- Section: contact
INSERT INTO public.cms_content (key, content, updated_at)
VALUES ('contact', '{"heroTitle":"Send Us a Message & Request Fast Quotes","heroLead":"Whether you require component data sheets, custom waveguide machining, or volume pricing, our application engineering team in Bengaluru is ready to assist.","careersTitle":"Join India’s Foremost RF & Microwave Engineering Hub","careersLead":"Accelerate your career in millimeter-wave technology, defense electronics, and satellite communications. Explore engineering opportunities at ICON Electromatic.","indiaOfficeName":"Icon Electromatic Pvt. Ltd. (India)","indiaAddress":"#303/2, 5th ‘A’ Cross, HRBR Layout, III Block,\nKalyan Nagar, Bengaluru – 560043","indiaPhone":"+91 80 2542 9452","indiaEmail":"salesiepl@iconelectromatic.com","singaporeOfficeName":"Icon Electromatic Singapore Pte Ltd","singaporeAddress":"204D Compassvale Drive #08-409\nSingapore 544204","singaporeEmail":"IESing@iconelectromatic.com","usaOfficeName":"Icon Electromatic LLC (USA)","usaAddress":"15412 Meadow Vista Dr, Edmond,\nOklahoma 73013, USA","usaPhone":"+1 405 593 5176","usaEmail":"salesiellc@iconelectromatic.com","hoursWeekday":"Monday – Friday: 9:00 AM – 6:00 PM IST","hoursWeekend":"Saturday: 9:30 AM – 1:30 PM IST","presets":["Enquiring about High Frequency Laminates & Prepregs.","Enquiring about Embedded Resistive Film.","Enquiring about 3D Printed Dielectric Parts.","Enquiring about High Power GaN Device and Beamforming IC.","Enquiring about High Power Switches and Limiter.","Enquiring about RF and MW Components.","Enquiring about Tunable Filters.","Enquiring about Software Defined Radios.","Enquiring about high voltage power supplies.","Enquiring about Temperature Sensors.","Enquiring about Thin Film Capacitors.","Enquiring about Ceramic Capacitors.","Enquiring about PCB Fabrication.","Enquiring about Perimeter Intrusion Detection System (PIDS)."],"careers":{"tabLabelSales":"Sales & RFQ Inquiry","tabLabelCareers":"Careers & Recruiting","showHiringBadge":true,"hiringBadgeText":"We''re Hiring","breadcrumbCareers":"Careers & Recruiting","eyebrowCareers":"ICON TALENT ACQUISITION","careersTitle":"Join India’s Foremost RF & Microwave Engineering Hub","careersLead":"Accelerate your career in millimeter-wave technology, defense electronics, and satellite communications. Explore engineering opportunities at ICON Electromatic.","careersHeroImage":"","introIcon":"fa-solid fa-users","introTitle":"Why Build Your Career at ICON?","introSubtitle":"RF & MICROWAVE EXCELLENCE","introDescription":"ICON ELECTROMATIC represents the world’s foremost RF, microwave, and high-frequency component manufacturers in India. Our engineers work at the bleeding edge of radar, space satellites, defense EW systems, and 5G/6G research.","benefits":[{"id":"ben-1","icon":"fa-solid fa-microchip","iconColor":"#60A5FA","title":"Global OEM Partnerships","description":"Direct technical engagement with leaders like Rogers Corporation, Qorvo, Spellman, Fortify, and YTTEK."},{"id":"ben-2","icon":"fa-solid fa-satellite-dish","iconColor":"#F87171","title":"Strategic Defense & Space Missions","description":"Contribute to critical airborne radars, missile guidance receivers, SATCOM transponders, and ISRO payloads."},{"id":"ben-3","icon":"fa-solid fa-flask-vial","iconColor":"#A855F7","title":"Advanced Microwave Measurement Lab","description":"Hands-on exposure to Vector Network Analyzers (VNA up to 67 GHz), noise figure meters, and RF anechoic test chambers."}],"showFormBadge":true,"formBadgeIcon":"fa-solid fa-briefcase","formBadgeText":"Talent Acquisition · Bengaluru & Pan-India","formTitle":"Apply for an Engineering Career","formSubtitle":"Join ICON Electromatic''s elite RF & Microwave applications team. Fill out the application form below and our technical panel will review your profile.","nameLabel":"Full Name *","namePlaceholder":"e.g. Vikram Sharma","nameRequired":true,"emailLabel":"Email Address *","emailPlaceholder":"vikram.sharma@example.com","emailRequired":true,"positionLabel":"Position *","positionPlaceholder":"Select Position...","positionRequired":true,"phoneLabel":"Phone / Mobile Number *","phonePlaceholder":"+91 98765 43210","phoneRequired":true,"cityLabel":"Current Location / City *","cityPlaceholder":"e.g. Bengaluru, Hyderabad, Pune, Chennai","cityRequired":true,"experienceLabel":"Total Experience *","experiencePlaceholder":"Select experience level...","experienceRequired":true,"organizationLabel":"Current Company or University *","organizationPlaceholder":"e.g. BEL, DRDO, Astra Microwave, IISc, IIT","organizationRequired":true,"noticeLabel":"Notice Period / Earliest Availability *","noticeRequired":true,"skillsLabel":"Key Technical Skills & RF EDA Tools *","skillsPlaceholder":"e.g. Keysight ADS, Ansys HFSS, CST Microwave Studio, VNA S-Parameters, GaN Matching, Rogers RT/duroid","skillsRequired":true,"showLinkedin":true,"linkedinLabel":"LinkedIn Profile or Online Portfolio","linkedinPlaceholder":"https://linkedin.com/in/username","linkedinRequired":false,"statementLabel":"Candidate Statement / Why ICON Electromatic? *","statementPlaceholder":"Briefly highlight your relevant RF, Microwave, or electronics experience, core projects, and why you are keen to join ICON Electromatic...","statementRequired":true,"resumeLabel":"Resume / Curriculum Vitae (PDF / DOCX) *","resumeHelpText":"Click or drop resume file (PDF/DOCX, max 10MB)","resumeAcceptedExtensions":".pdf,.doc,.docx","resumeMaxSizeMb":10,"resumeRequired":true,"positions":["RF & Microwave Design Engineer (DC–110 GHz)","Field Applications Engineer (FAE) - RF Components","Technical Sales & OEM Account Manager","Radar, EW & SATCOM Systems Application Specialist","RF Lab Test & Measurement Specialist (VNA/Spectrum)","High-Frequency PCB & PTFE Substrates Specialist","Graduate RF Engineering Trainee / Intern","Other Technical / Engineering Specialist"],"experienceLevels":["Fresh Graduate / Final Year (< 1 Year)","1 – 3 Years Experience","3 – 5 Years (Mid-Level Engineer)","5 – 8 Years (Senior RF Specialist)","8+ Years (Principal / Lead Engineer)"],"noticeOptions":["Immediate / Less than 15 Days","30 Days","60 Days","90 Days"],"submitButtonIcon":"fa-solid fa-briefcase","submitButtonText":"Submit Engineering Application","successTitle":"Application Received!","successSubtitle":"Thank you, {name}.","successMessage":"Your application for {position} has been logged with our Technical Evaluation Committee and Talent Acquisition team in Bengaluru.","candidateIdPrefix":"ICON-CAREER-","nextStepsTitle":"Next Steps:","nextStepsText":"Qualified candidates will be contacted within 3 to 5 business days for an introductory technical discussion. For updates, quote your Candidate Application ID to careers@iconelectromatic.com.","careersEmail":"careers@iconelectromatic.com","resetButtonText":"Submit Another Application","validationErrorMessage":"Please complete all required fields and attach your resume before submitting.","errorMessage":"An error occurred while submitting your application. Please check your connection and try again.","resumeFormatErrorMessage":"Invalid file format. Please upload an accepted file type: {types}","resumeSizeErrorMessage":"File size ({size} MB) exceeds the maximum allowed limit of {max} MB."}}'::jsonb, timezone('utc'::text, now()))
ON CONFLICT (key) DO UPDATE SET
    content = EXCLUDED.content,
    updated_at = timezone('utc'::text, now());

