-- Section: partners
INSERT INTO public.cms_content (key, content, updated_at)
VALUES ('partners', '{"heroTitle":"Authorized Technology Partners","heroLead":"We represent a diverse portfolio of OEMs across sectors, industries and application.<br />To know more about their products, make an enquiry or request samples just get in touch with us.","trustBadge1":"10+ Global Technology Partners","trustBadge2":"Space & Mil-Spec Screening Support","partners":[{"id":"rogers","name":"Rogers Corporation","domain":"High-Frequency Laminates & Prepregs","category":"materials","accentColor":"red","logoImg":"/images/oem-logos/Rogers_Logo_no_bg.png","description":"A global leader in engineered materials, Rogers provides high-frequency laminates and prepregs widely used in radar, aerospace, defence, and high-speed communication systems where signal integrity and reliability are critical.","website":"https://www.rogerscorp.com"},{"id":"mini-circuits","name":"Mini-Circuits","domain":"RF & Microwave Components","category":"components","accentColor":"red","logoImg":"/images/oem-logos/mini-circuits-seeklogo.png","description":"Mini-Circuits offers an extensive portfolio of RF and microwave components supporting design, prototyping, and production across defence, SATCOM, test & measurement, and advanced communication platforms.","website":"https://www.minicircuits.com"},{"id":"qorvo","name":"Qorvo","domain":"RF, mmWave & Active Antenna Solutions","category":"semiconductors","accentColor":"blue","logoImg":"/images/oem-logos/Qorvo_logo_wb.png","description":"Qorvo develops advanced RF and mmWave technologies including RFICs, Power amplifiers, Switches, Converters, and Active antenna ASICs, enabling high-performance Radar, SATCOM, and next-generation Wireless systems.","website":"https://www.qorvo.com"},{"id":"tecdia","name":"Tecdia","domain":"Precision Capacitors & Thin-Film Components","category":"components","accentColor":"blue","logoImg":"/images/oem-logos/Tecdia_cropped.png","description":"Tecdia manufactures single-layer capacitors, thin-film chip resistors, mmWave varactors, and ground blocks for demanding aerospace, defence, medical, and RF applications.","website":"https://www.tecdia.com"},{"id":"tri-teq","name":"Tri-TeQ","domain":"Tunable Filters & RF Assemblies","category":"components","accentColor":"red","logoImg":"/images/oem-logos/TriTeq_logo_wb.png","description":"Tri-TeQ is a leader in harmonic switch filter banks, high/low and tunable band-pass filters, and multifunction RF assemblies used in defence, SATCOM, and electronic warfare systems.","website":"https://www.tri-teq.com"},{"id":"rfuw","name":"RFuW Engineering","domain":"High-Performance RF Switches & Modules","category":"components","accentColor":"red","logoImg":"/images/oem-logos/RFuW_Logo.png","description":"RFuW Engineering specialises in rugged RF switches, limiters, and integrated microwave modules designed for high-power, wideband, and mission-critical aerospace and defence applications.","website":"https://www.rfuw.com"},{"id":"yttek","name":"YTTEK","domain":"Software-Defined Radio (SDR) Platforms","category":"semiconductors","accentColor":"blue","logoImg":"/images/oem-logos/YTTEK_Logo_wb.png","description":"YTTEK builds flexible and reconfigurable software-defined radio platforms supporting research, defence, and advanced wireless communication applications.","website":"https://www.yttek.com"},{"id":"quantic-eulex","name":"Quantic Eulex / Evans","domain":"Advanced Ceramic Microwave & Hybrid Capacitors","category":"components","accentColor":"blue","logoImg":"/images/oem-logos/Evans_logo.png","description":"Quantic Eulex & Evans Hybrid Capacitors engineer high-energy, high-frequency ceramic capacitors and hybrid capacitor banks supporting radar, SATCOM, aerospace, and space platforms.","website":"https://www.quanticdevices.com"},{"id":"quantic-ohmega","name":"Quantic Ohmega-Ticer","domain":"Embedded Thin-Film Resistive Materials","category":"materials","accentColor":"blue","logoImg":"/images/oem-logos/OhmegaTicer_Black.png","description":"Ohmega-Ticer provides embedded thin-film resistive copper foils that enable compact, high-performance digital and RF PCB designs for defence, aerospace, and advanced electronics.","website":"https://www.ohmega.com"},{"id":"thermosen","name":"Thermosen Technologies","domain":"Temperature Sensors for Hi-Rel Applications","category":"sensors","accentColor":"blue","logoImg":"/images/oem-logos/Thermosen_logo.png","description":"Thermosen develops temperature sensing solutions focused on Hi-Rel, aerospace, and defence sectors, ensuring accurate thermal monitoring in extreme environments.","website":"https://www.thermosen.com"},{"id":"fortify","name":"Fortify","domain":"Dielectric 3D Printing for RF & Microwave Devices","category":"materials","accentColor":"blue","logoImg":"/images/oem-logos/Fortify_Logo_Black_Bg.png","description":"Fortify enables advanced dielectric 3D printing materials for RF and microwave components, supporting complex geometries, rapid prototyping, and next-generation device development.","website":"https://www.fortify3d.com"},{"id":"powerfactor","name":"PowerFactor Electronics (PowerRF)","domain":"Power Electronics & RF Microwave Domains","category":"components","accentColor":"blue","logoImg":"/PICTURES/PowerRFlogo Vert Logo1.jpg","description":"Specialized in R&D, design, testing, consultancy, and product development in Power Electronics and RF Microwave domains under the Make in India initiative.","website":"https://powerrf.in"},{"id":"nee","name":"NEE International (New Era Electronics)","domain":"Application PCBs for Microwave & Satellite Communication","category":"sensors","accentColor":"red","logoImg":"/images/oem-logos/NEE_Logo_wb.png","description":"NEE International is a leading fabricator of microwave and satellite communication PCBs, supporting high-frequency and space-grade electronic applications.","website":"https://neeinternational.com"}]}'::jsonb, timezone('utc'::text, now()))
ON CONFLICT (key) DO UPDATE SET
    content = EXCLUDED.content,
    updated_at = timezone('utc'::text, now());

-- Section: blogs
INSERT INTO public.cms_content (key, content, updated_at)
VALUES ('blogs', '{"heroTitle":"OEM Technical News, Video Demos & Insights","heroSubtitle":"Direct technical bulletins, video demonstrations, application whitepapers, and product release updates from ICON Electromatic''s 15 global manufacturing partners.","trustBadge1":"Application Whitepapers & Notes","trustBadge2":"Video Demos & Technical Webinars","trustBadge3":"Direct Manufacturer Bulletins","oemBlogs":[{"oemId":"rogers-corporation","officialWebsite":"https://www.rogerscorp.com/advanced-electronics-solutions","portalName":"Rogers AES Technology Center","headline":"Advanced High-Frequency PTFE & Ceramic Substrates for Millimeter-Wave Radars","visible":true,"articles":[{"id":"rogers-art-1","title":"Rogers Unveils Next-Gen RT/duroid® Formulations for 77–81 GHz Automotive Radars","date":"September 2026","category":"Materials Innovation","readTime":"5 min read","image":"/images/rf-laminate.jpg","summary":"New micro-dispersion glass microfiber composites reduce dielectric loss tangent down to 0.0009 at 77 GHz while preserving dimensional stability across -55°C to +125°C automotive qualification cycles.","content":"\n          <p>As commercial automotive radars transition to high-definition 77–81 GHz imaging architectures, dielectric consistency and low insertion loss have become fundamental design constraints. Rogers Corporation has announced enhanced RT/duroid® composite formulations specifically tailored for millimeter-wave antenna-in-package (AiP) and microstrip patch arrays.</p>\n          <h4>Key Engineering Advantages:</h4>\n          <ul>\n            <li><strong>Dielectric Constant Tolerance:</strong> Tight Dk control of 2.20 ± 0.02 across the entire production lot, minimizing beam squint in phased array radar sensors.</li>\n            <li><strong>Extremely Low Dissipation Factor:</strong> Tan δ of 0.0009 at 77 GHz ensures maximum transmit power efficiency and received signal-to-noise ratio (SNR).</li>\n            <li><strong>Reverse-Treated Copper Foil:</strong> Ultralow surface roughness (Rq < 0.3 µm) eliminates conductor loss spikes typical in sub-THz frequency bands.</li>\n          </ul>\n          <p>ICON Electromatic stocks certified RT/duroid panels for defense radar, automotive prototyping, and satellite transceivers with complete lot traceability.</p>\n        ","tags":["77 GHz Radar","RT/duroid","PTFE Substrate","Automotive"],"visible":true},{"id":"rogers-art-2","title":"RO4000® Series Evolution: Combining FR-4 Processing Simplicity with Millimeter-Wave Performance","date":"August 2026","category":"Manufacturing Guide","readTime":"4 min read","image":"/images/rf-microwave-pcb.jpg","summary":"A technical review of RO4350B and RO4003C thermoset ceramic laminates enabling standard standard multi-layer PCB lamination without specialized plasma sodium treatment.","content":"\n          <p>Traditional PTFE laminates require specialized sodium etching or plasma surface preparation prior to through-hole plating. Rogers RO4000® series thermoset hydrocarbon ceramic laminates overcome this hurdle, processing like standard FR-4 while delivering microwave electrical performance.</p>\n          <h4>Fabrication & Electrical Highlights:</h4>\n          <ul>\n            <li>Compatible with automated surface-mount assembly and lead-free SAC305 reflow profiles up to 280°C.</li>\n            <li>Low Z-axis coefficient of thermal expansion (CTE 31 ppm/°C) matches copper, preventing plated through-hole (PTH) barrel fatigue under severe thermal shock.</li>\n            <li>Excellent thermal conductivity (0.62 W/m/K) provides efficient passive heat spreading under surface-mount power amplifiers.</li>\n          </ul>\n        ","tags":["RO4350B","PCB Fabrication","Thermoset","High-Rel"],"visible":true}],"videos":[{"id":"rogers-vid-1","title":"Dielectric Material Characterization at W-Band (75 to 110 GHz)","speaker":"John Coonrod, Technical Marketing Director","duration":"18:40","date":"October 2026","thumbnail":"/images/rf-laminate.jpg","videoUrl":"","summary":"A technical webinar exploring cavity perturbation and split-post dielectric resonator methods for accurately extracting Dk and Df up to 110 GHz.","topics":["Sub-THz Metrology","Skin Depth Effects","Microstrip Resonators"],"visible":true},{"id":"rogers-vid-2","title":"Optimizing Microstrip-to-CPW Transitions on RT/duroid 5880","speaker":"Dr. Allen Ward, Senior Application Specialist","duration":"14:15","date":"July 2026","thumbnail":"/images/rf-microwave-pcb.jpg","videoUrl":"","summary":"Step-by-step layout considerations for ground-coplanar waveguide (GCPW) feedlines to eliminate parasitic mode propagation in aerospace antennas.","topics":["GCPW Transitions","Parasitic Modes","Via Stitching"],"visible":true}],"whitepapers":[{"id":"rogers-wp-1","title":"Thermal Management Strategies for Multi-Layer High-Power RF Amplifiers","author":"Rogers Corporation Advanced Electronics Lab","date":"June 2026","pages":"16 Pages","frequencyBand":"DC to 28 GHz","summary":"Comparative analysis of copper backplane bonding, coin insertion, and high-conductivity TC-series laminates for high-power radar transmitters.","keyFindings":["TC350 Plus reduces amplifier junction temperatures by up to 22°C vs conventional FR-4.","Direct copper bonded (DCB) substrates eliminate thermal grease interface resistances.","Continuous thermal rating up to 170°C for airborne radar pods."],"downloadUrl":"","visible":true}],"officialLinks":[{"title":"Rogers AES Technology Center","url":"https://www.rogerscorp.com/advanced-electronics-solutions","description":"Access official Rogers design calculators, material property tables, and laminate selector guides.","icon":"fa-globe"},{"title":"Rogers ROG RF Calculator Hub","url":"https://www.rogerscorp.com/advanced-electronics-solutions/design-hub","description":"Interactive microstrip and stripline impedance synthesis calculator with copper roughness modeling.","icon":"fa-calculator"}]},{"oemId":"qorvo","officialWebsite":"https://www.qorvo.com","portalName":"Qorvo Design & Engineering Hub","headline":"High-Power GaN-on-SiC MMICs & Active Phased Array Beamforming ICs","visible":true,"articles":[{"id":"qorvo-art-1","title":"Qorvo Launches 100W X-Band GaN Power Amplifier with >48% Power-Added Efficiency","date":"September 2026","category":"Semiconductor Breakthrough","readTime":"6 min read","image":"/images/gan-power-chip.jpg","summary":"Targeting next-generation active electronically scanned arrays (AESA), Qorvo’s latest GaN-on-SiC MMIC provides 100W pulsed output power in an ultracompact surface-mount package.","content":"\n          <p>Modern military radar and airborne surveillance payloads demand massive radiated RF power within strict thermal and size envelopes. Qorvo has unveiled its new generation of X-band (8.5 to 10.5 GHz) gallium nitride on silicon carbide (GaN-on-SiC) high-power amplifiers.</p>\n          <h4>Key Performance Metrics:</h4>\n          <ul>\n            <li><strong>Saturated Output Power:</strong> Exceeds 50 dBm (100 Watts) across the full 8.5–10.5 GHz band under pulsed radar conditions.</li>\n            <li><strong>Power-Added Efficiency (PAE):</strong> Greater than 48% at nominal bias, significantly reducing cooling payload requirements for phased array tiles.</li>\n            <li><strong>Integrated Protection:</strong> Built-in gate pulse sequencing and RF power overdrive detectors ensure fail-safe operation in dense RF emitter environments.</li>\n          </ul>\n        ","tags":["X-Band Radar","GaN MMIC","AESA","Defense"],"visible":true},{"id":"qorvo-art-2","title":"Dual-Polarization Ka-Band Beamforming ICs Revolutionize LEO Satellite Terminals","date":"August 2026","category":"SATCOM Innovation","readTime":"5 min read","image":"/images/gan-power-chip.jpg","summary":"Qorvo integrated 8-channel transmit/receive beamformers with 6-bit phase and 6-bit amplitude control, enabling dynamic satellite tracking without mechanical gimbals.","content":"\n          <p>Low-Earth-Orbit (LEO) satellite communications require electronically steered phased arrays capable of maintaining multi-gigabit user links across rapid orbital overhead passes. Qorvo’s Ka-band beamforming ASICs integrate bidirectional amplifiers, phase shifters, and attenuators into a single monolithic die.</p>\n        ","tags":["Ka-Band","Beamforming","LEO Satellites","Phased Array"],"visible":true}],"videos":[{"id":"qorvo-vid-1","title":"Thermal Modeling & Pulsed Biasing for GaN-on-SiC Power Amplifiers","speaker":"David Aichele, VP Defense & Aerospace Solutions","duration":"22:10","date":"September 2026","thumbnail":"/images/gan-power-chip.jpg","videoUrl":"","summary":"Critical electrical considerations for drain voltage pulsing, thermal time constants, and transient load line stability in high-power radar transmitters.","topics":["Pulsed Radar Biasing","Thermal Resistance Rth","VSWR Tolerance"],"visible":true},{"id":"qorvo-vid-2","title":"Integrating 16-Channel Core Chips into Flat-Panel Phased Arrays","speaker":"Dr. Michael Chen, Principal Systems Architect","duration":"16:50","date":"July 2026","thumbnail":"/images/gan-power-chip.jpg","videoUrl":"","summary":"Architecture overview of tile-based active phased arrays utilizing SPI control and calibrated beam tables.","topics":["Tile Arrays","SPI Digital Control","Phase Calibration"],"visible":true}],"whitepapers":[{"id":"qorvo-wp-1","title":"Optimizing Efficiency and Linearity in Wideband GaN Power Amplifiers","author":"Qorvo Advanced Defense Applications Group","date":"May 2026","pages":"20 Pages","frequencyBand":"2.0 to 18.0 GHz","summary":"Harmonic termination networks and digital predistortion (DPD) co-design methodologies for multi-octave electronic warfare transmitters.","keyFindings":["Second and third harmonic tuning enhances PAE by 12% across multi-octave bandwidths.","GaN-on-SiC demonstrates 5x higher power density compared to equivalent GaAs pHEMT devices.","MTTF exceeds 10^7 hours at 200°C channel junction temperatures."],"downloadUrl":"","visible":true}],"officialLinks":[{"title":"Qorvo Official Technical Hub","url":"https://www.qorvo.com/design-hub","description":"Explore S-parameter downloads, nonlinear large-signal models, and evaluation board user manuals.","icon":"fa-microchip"},{"title":"Qorvo MatchCalc Impedance Matching Tool","url":"https://www.qorvo.com/design-hub/design-tools/matchcalc","description":"Interactive Smith chart synthesis tool for discrete and distributed RF matching networks.","icon":"fa-chart-line"}]},{"oemId":"fortify","officialWebsite":"https://3dfortify.com","portalName":"Fortify RF Dielectric Optics Lab","headline":"3D Printed Low-Loss Dielectric Lenses, Antennas & GRIN RF Optics","visible":true,"articles":[{"id":"fortify-art-1","title":"Fortify Unveils Radix™ 2.8 Dielectric Material for Tailored 3D Lens Antennas","date":"October 2026","category":"Additive RF Optics","readTime":"4 min read","image":"/images/dielectric-3d-lens.jpg","summary":"Using patented Digital Composite Manufacturing (DCM), Fortify produces low-loss (Df < 0.001) Luneburg and Maxwell fish-eye lenses up to 110 GHz with custom dielectric gradations.","content":"\n          <p>Traditional manufacturing of graded-index (GRIN) microwave optics requires complex machining of concentric dielectric shells with unpredictable air gaps. Fortify’s additive photopolymerization platform directly prints monolithic Luneburg lenses with continuous internal dielectric variation.</p>\n          <h4>Radix™ Material Performance:</h4>\n          <ul>\n            <li><strong>Dielectric Constant Flexibility:</strong> Tunable Dk from 1.5 to 4.5 in a single printed structure.</li>\n            <li><strong>Ultralow RF Loss:</strong> Dissipation factor below 0.0012 across Ka, V, and W-bands.</li>\n            <li><strong>Mass Reduction:</strong> Cellular lattice topologies reduce total antenna weight by 60% compared to solid teflon optics.</li>\n          </ul>\n        ","tags":["3D Printing","Radix Material","Luneburg Lens","Sub-THz"],"visible":true}],"videos":[{"id":"fortify-vid-1","title":"Demonstration: 3D Printing Wide-Angle Luneburg Lenses for SATCOM","speaker":"Karlo Delos Reyes, VP Applications","duration":"15:20","date":"September 2026","thumbnail":"/images/dielectric-3d-lens.jpg","videoUrl":"","summary":"Live laboratory testing comparing a Fortify 3D printed dielectric lens antenna against a traditional parabolic reflector at 28 GHz.","topics":["Beam Steering","GRIN Lenses","Additive Manufacturing"],"visible":true}],"whitepapers":[{"id":"fortify-wp-1","title":"Graded-Index Dielectric Lenses for Millimeter-Wave Beam Steering","author":"Fortify RF Engineering Team","date":"July 2026","pages":"12 Pages","frequencyBand":"18 to 90 GHz","summary":"Electromagnetic simulation and chamber validation of 3D printed microwave lenses achieving ±60° scan angles with zero mechanical wear.","keyFindings":["Gain enhancement of +18 dBi achieved over bare horn feed at 38 GHz.","Zero internal reflection at graded dielectric boundaries eliminates focal point degradation.","High glass transition temperature (Tg > 165°C) withstands harsh outdoor airborne operating environments."],"downloadUrl":"","visible":true}],"officialLinks":[{"title":"Fortify RF Optics Technology Hub","url":"https://3dfortify.com/applications/rf-devices-antennas/","description":"Case studies, Radix resin technical data sheets, and custom 3D lens design guidelines.","icon":"fa-cube"}]},{"oemId":"minicircuits","officialWebsite":"https://www.minicircuits.com","portalName":"Mini-Circuits Technical Portal","headline":"Precision RF, Microwave & Millimeter-Wave Components DC to 100 GHz","visible":true,"articles":[{"id":"mini-art-1","title":"Mini-Circuits Expands Ultra-Wideband Connectorized Amplifiers Covering 0.5 to 40 GHz","date":"September 2026","category":"Product Release","readTime":"4 min read","image":"/images/rf-filter.jpg","summary":"New ZX60 and ZVE series instrumentation-grade amplifiers deliver +22 dBm P1dB, low 2.8 dB noise figure, and hermetic ruggedized packaging for lab and field telemetry.","content":"\n          <p>Mini-Circuits has announced the latest additions to its field-proven coaxial amplifier portfolio. Incorporating proprietary GaAs and GaN MMIC designs, these plug-and-play modules streamline test benches and military comms testing.</p>\n        ","tags":["Wideband Amplifier","Test Bench","Coaxial","Instrumentation"],"visible":true}],"videos":[{"id":"mini-vid-1","title":"Understanding Linearity & IP3 in Wideband Frequency Mixers","speaker":"Mini-Circuits Applications Engineering Group","duration":"19:30","date":"August 2026","thumbnail":"/images/rf-filter.jpg","videoUrl":"","summary":"A deep-dive tutorial explaining two-tone intermodulation distortion, LO drive optimization, and balance topologies in double-balanced diode mixers.","topics":["Mixer Linearity","IIP3 Optimization","Spur Charts"],"visible":true}],"whitepapers":[{"id":"mini-wp-1","title":"High-Rejection Miniature Cavity Filter Design Techniques","author":"Mini-Circuits Filter Solutions Division","date":"May 2026","pages":"14 Pages","frequencyBand":"1 to 20 GHz","summary":"Addressing thermal drift and insertion loss trade-offs in sub-miniature combline and interdigital cavity filters.","keyFindings":["Invar temperature compensation keeps center frequency drift under 5 ppm/°C.","Silver plating thickness of 5 skin depths yields insertion loss < 0.8 dB at 10 GHz."],"downloadUrl":"","visible":true}],"officialLinks":[{"title":"Mini-Circuits Official Component Search","url":"https://www.minicircuits.com","description":"Comprehensive parametric search engine covering over 10,000 RF/microwave catalog components.","icon":"fa-magnifying-glass"}]},{"oemId":"ohmega-ticer","officialWebsite":"https://www.ohmega.com","portalName":"Ohmega Ticer Thin Film Technology Center","headline":"Embedded Thin-Film Resistor Foils for High-Density Multi-Layer PCBs","visible":true,"articles":[{"id":"ohmega-art-1","title":"OhmegaPly® RCM Foils Eliminate Surface Resistors in 100 Gbps High-Speed Backplanes","date":"September 2026","category":"Embedded Passives","readTime":"5 min read","image":"/images/rf-microwave-pcb.jpg","summary":"By embedding thin-film nickel-phosphorous resistors directly into internal PCB copper layers, parasitic inductance is reduced to near zero, enabling pristine digital eye diagrams.","content":"\n          <p>Surface-mount chip resistors introduce substantial solder joint parasitic capacitance and lead inductance that degrade signal integrity in high-speed PAM4 and 112G SerDes channels. OhmegaPly® RCM (Resistor-Conductor-Material) allows resistors to be etched internally on planar copper foils, clearing top-layer routing space.</p>\n        ","tags":["Embedded Resistors","Thin Film","High-Speed Digital","Signal Integrity"],"visible":true}],"videos":[{"id":"ohmega-vid-1","title":"Fabricating Embedded Thin Film Resistors: PCB Etch Process Walkthrough","speaker":"Bruce Mahler, VP Engineering","duration":"17:10","date":"June 2026","thumbnail":"/images/rf-microwave-pcb.jpg","videoUrl":"","summary":"Detailed chemical etch chemistries and laser trimming procedures for achieving ±1% tolerance on internal PCB embedded resistors.","topics":["PCB Processing","Laser Trimming","Differential Etching"],"visible":true}],"whitepapers":[{"id":"ohmega-wp-1","title":"Reliability and Power Handling of Embedded Resistor Foils under Thermal Shock","author":"Ohmega Ticer Reliability Laboratories","date":"April 2026","pages":"15 Pages","frequencyBand":"DC to 50 GHz","summary":"Military qualification testing validating OhmegaPly foils through 2,000 cycles of thermal shock (-65°C to +150°C) without resistance drift.","keyFindings":["Resistance change under 0.25% after 2,000 MIL-STD-202 Method 107 cycles.","Zero wire bonds or solder joints to fatigue in high-vibration aerospace avionics."],"downloadUrl":"","visible":true}],"officialLinks":[{"title":"Ohmega Technologies Official Design Portal","url":"https://www.ohmega.com/technical-information/","description":"Design rules, CAD layout footprints, and chemical processing guidelines for embedded resistor foils.","icon":"fa-file-lines"}]},{"oemId":"rfuw-engineering","officialWebsite":"https://www.rfuw-engineering.com","portalName":"RFuW High-Power Protection Lab","headline":"High-Power Surface-Mount SMT PIN Diode Limiters & High-Isolation Switches","visible":true,"articles":[{"id":"rfuw-art-1","title":"RFuW Releases 100W SMT Limiter Series Protecting Sensitive LNAs up to 18 GHz","date":"August 2026","category":"RF Protection","readTime":"4 min read","image":"/images/gan-power-chip.jpg","summary":"MSL1 surface-mount limiters withstand continuous 100W CW power and 500W peak pulsed power while clamping flat leakage below +13 dBm to safeguard sensitive receiver front-ends.","content":"\n          <p>Radar receiver protection requires instantaneous clamping when exposed to co-site transmitter leakage or external electronic countermeasure (ECM) pulses. RFuW Engineering’s multi-stage diode limiters eliminate bulky coaxial hardware with tiny SMT quad-flat packages.</p>\n        ","tags":["Receiver Protection","PIN Diode","LNA Limiter","SMT"],"visible":true}],"videos":[{"id":"rfuw-vid-1","title":"Radar Receiver Protection: Spike Leakage vs Flat Leakage Explained","speaker":"Tim Gallic, Principal Applications Engineer","duration":"14:40","date":"May 2026","thumbnail":"/images/gan-power-chip.jpg","videoUrl":"","summary":"Laboratory oscilloscope captures demonstrating sub-nanosecond recovery time and spike leakage energy mitigation during 1kW radar pulse events.","topics":["Spike Leakage","Recovery Time","Co-Site Blinding"],"visible":true}],"whitepapers":[{"id":"rfuw-wp-1","title":"High-Power SMT PIN Diode Switches for Tactical Military Communications","author":"RFuW Applications Group","date":"March 2026","pages":"11 Pages","frequencyBand":"20 MHz to 6.0 GHz","summary":"Engineering analysis of cold-switching vs hot-switching power capabilities in SP2T and SP4T symmetrical diode topologies.","keyFindings":["Isolation exceeds 50 dB at 2 GHz in a 4x4 mm ceramic QFN package.","Integrated DC blocking capacitors prevent accidental ground bias shorting."],"downloadUrl":"","visible":true}],"officialLinks":[{"title":"RFuW Engineering Official Site","url":"https://www.rfuw-engineering.com","description":"Datasheets and SMT PCB layout Gerber footprints for high-power limiters and RF switches.","icon":"fa-shield-halved"}]},{"oemId":"triteq","officialWebsite":"https://www.triteq.com","portalName":"Tri-TeQ Filter Solutions Hub","headline":"Harmonic Switched Filters & Tactical Frequency Hopping Comms","visible":true,"articles":[{"id":"triteq-art-1","title":"Tri-TeQ Unveils Fast-Hopping Harmonic Filter Banks for Software-Defined Tactical Transceivers","date":"July 2026","category":"Tactical Hardware","readTime":"5 min read","image":"/images/rf-filter.jpg","summary":"Sub-microsecond switched harmonic filter banks suppress second and third order harmonics by >50 dB across 30–512 MHz tactical VHF/UHF frequency bands.","content":"\n          <p>Tactical military communications utilize rapid frequency hopping to resist electronic jamming. Tri-TeQ’s digitally controlled harmonic filter units switch between pre-tuned bandpass channels in under 500 nanoseconds, maintaining compliance with MIL-STD-188 harmonics standards.</p>\n        ","tags":["Harmonic Filter","Frequency Hopping","Tactical Radio","VHF/UHF"],"visible":true}],"videos":[{"id":"triteq-vid-1","title":"Bench Test: Harmonic Rejection During 10,000 Hops/sec Tactical Transmission","speaker":"Tri-TeQ Defense Systems Team","duration":"11:20","date":"April 2026","thumbnail":"/images/rf-filter.jpg","videoUrl":"","summary":"Real-time spectrum analyzer demonstration showing clean harmonic suppression during extreme frequency agile transmissions.","topics":["Frequency Agile","Harmonic Suppression","Transient Settling"],"visible":true}],"whitepapers":[{"id":"triteq-wp-1","title":"Co-Site Interference Cancellation Using Digitally Tuned Harmonic Filters","author":"Tri-TeQ Engineering Division","date":"January 2026","pages":"10 Pages","frequencyBand":"30 MHz to 2.5 GHz","summary":"Methodology for operating multiple high-power tactical transmitters simultaneously on naval masts without intermodulation receiver desensitization.","keyFindings":["Insertion loss under 1.2 dB across active passband preserves transmit power efficiency.","Hermetically sealed enclosure compliant with MIL-STD-810G immersion standards."],"downloadUrl":"","visible":true}],"officialLinks":[{"title":"Tri-TeQ Engineering Official Portal","url":"https://www.triteq.com","description":"Custom harmonic filter specifications and military tactical communication solutions.","icon":"fa-tower-broadcast"}]},{"oemId":"yttek","officialWebsite":"https://www.yttek.com","portalName":"YTTEK Software Defined Radio Center","headline":"Ultra-Wideband Software Defined Radios (HyperSDR) for EW & 5G/6G Research","visible":true,"articles":[{"id":"yttek-art-1","title":"HyperSDR 4x4 Transceiver Platform Reaches 100 kHz to 18 GHz Instantaneous Coverage","date":"August 2026","category":"SDR Hardware","readTime":"6 min read","image":"/images/rf-microwave-pcb.jpg","summary":"Featuring onboard Xilinx Ultrascale+ RFSoC and direct RF sampling converters, HyperSDR enables instantaneous spectrum monitoring and multi-channel beamforming experimentation.","content":"\n          <p>Traditional SDRs rely on multi-stage analog downconversion that introduces phase imbalances and local oscillator leakage. YTTEK’s HyperSDR platform integrates 14-bit ADCs and DACs operating directly up to 18 GHz, streamlining electronic warfare (EW) and cognitive radio development.</p>\n        ","tags":["HyperSDR","RFSoC","Direct RF Sampling","Electronic Warfare"],"visible":true}],"videos":[{"id":"yttek-vid-1","title":"HyperSDR Live Demo: 1 GHz Real-Time Spectrum Recording & Playback","speaker":"YTTEK System Applications Group","duration":"16:05","date":"July 2026","thumbnail":"/images/rf-microwave-pcb.jpg","videoUrl":"","summary":"Demonstrating 100 GbE streaming of raw I/Q samples to NVMe storage arrays with zero dropped samples during radar emitter simulation.","topics":["I/Q Recording","100 GbE Streaming","FPGA Processing"],"visible":true}],"whitepapers":[{"id":"yttek-wp-1","title":"Phase-Coherent Multi-Channel Calibration for 5G FR2 & 6G Testbeds","author":"YTTEK Advanced Wireless Lab","date":"February 2026","pages":"18 Pages","frequencyBand":"100 kHz to 44 GHz","summary":"Digital calibration techniques ensuring sub-degree phase synchronization across 32 synchronized HyperSDR transceivers.","keyFindings":["Inter-channel phase jitter measured below 120 femtoseconds RMS.","Full API compatibility with GNU Radio, MATLAB, and custom C++ pipelines."],"downloadUrl":"","visible":true}],"officialLinks":[{"title":"YTTEK Official Product & SDK Portal","url":"https://www.yttek.com","description":"Software-defined radio firmware downloads, API documentation, and RFSoC tutorials.","icon":"fa-satellite-dish"}]},{"oemId":"spellman","officialWebsite":"https://www.spellmanhv.com","portalName":"Spellman High Voltage Technical Center","headline":"Precision High-Voltage DC Power Supplies & X-Ray Generators","visible":true,"articles":[{"id":"spellman-art-1","title":"Spellman Introduces Modular 100kV Ultra-Low Ripple Power Supplies for Vacuum Tube TWTAs","date":"August 2026","category":"High Voltage DC","readTime":"4 min read","image":"/images/gan-power-chip.jpg","summary":"Compact high-voltage DC modules provide <0.001% peak-to-peak voltage ripple, safeguarding traveling wave tubes (TWT) and electron gun filaments in satellite uplink transmitters.","content":"\n          <p>High-power microwave vacuum devices such as klystrons and traveling wave tube amplifiers (TWTAs) require extraordinarily stable DC bias potentials. Spellman’s modular high-voltage power converters incorporate resonant inverter topologies that eliminate high-frequency switching hash from radiated RF signals.</p>\n        ","tags":["High Voltage","TWTA Power","Low Ripple","Vacuum Electronics"],"visible":true}],"videos":[{"id":"spellman-vid-1","title":"High Voltage Safety & Arc Fault Recovery in Microwave Transmitters","speaker":"Spellman Power Systems Lab","duration":"13:50","date":"March 2026","thumbnail":"/images/gan-power-chip.jpg","videoUrl":"","summary":"Demonstration of sub-microsecond electronic crowbar circuits protecting expensive electron tube grids during vacuum flashover events.","topics":["Arc Protection","Crowbar Circuits","Safety Protocols"],"visible":true}],"whitepapers":[{"id":"spellman-wp-1","title":"Minimizing Phase Noise in TWT Radar Transmitters via Ultra-Clean HV Biasing","author":"Spellman High Voltage Electronics Corp.","date":"May 2026","pages":"12 Pages","frequencyBand":"High Voltage DC","summary":"Mathematical modeling linking high voltage collector ripple to transmitter Doppler phase noise skirts in long-range search radar.","keyFindings":["Ripple reduction to 10 ppm improves radar Doppler sub-clutter visibility by 8 dB.","Solid-state encapsulation allows high-altitude airborne operation up to 50,000 feet without corona breakdown."],"downloadUrl":"","visible":true}],"officialLinks":[{"title":"Spellman High Voltage Electronics Official Site","url":"https://www.spellmanhv.com","description":"Technical application notes on high-voltage power supplies, X-ray sources, and custom OEM converters.","icon":"fa-bolt-lightning"}]},{"oemId":"thermosen","officialWebsite":"https://www.thermosen.com","portalName":"Thermosen Sensor Labs","headline":"High-Precision Temperature Sensors for High-Reliability RF Systems","visible":true,"articles":[{"id":"thermosen-art-1","title":"Thermosen Miniaturized Platinum RTD Sensors Provide 0.05°C Precision in GaN Thermal Feedback","date":"June 2026","category":"Sensors & Telemetry","readTime":"3 min read","image":"/images/gan-power-chip.jpg","summary":"Micro-footprint SMD resistance temperature detectors (RTDs) mounted directly adjacent to GaN amplifier MMICs provide real-time junction temperature tracking.","content":"\n          <p>Proper thermal protection of GaN MMICs requires sensing temperatures within millimeters of active device gates. Thermosen’s platinum thin-film sensors withstand reflow temperatures up to 350°C and maintain linear accuracy across -70°C to +300°C.</p>\n        ","tags":["RTD Sensor","Thermal Feedback","GaN Protection","Precision Sensing"],"visible":true}],"videos":[{"id":"thermosen-vid-1","title":"Real-Time Dynamic Thermal Throttling for Phased Array Transmit Modules","speaker":"Thermosen Engineering Team","duration":"10:45","date":"February 2026","thumbnail":"/images/gan-power-chip.jpg","videoUrl":"","summary":"Live telemetry tracking amplifier heatsink temperatures during continuous wave radar transmission at maximum duty cycle.","topics":["Closed-Loop Throttling","Platinum RTD","Reliability"],"visible":true}],"whitepapers":[{"id":"thermosen-wp-1","title":"Cryogenic to High-Temperature Sensor Performance in Satellite Telemetry","author":"Thermosen Reliability Team","date":"January 2026","pages":"9 Pages","frequencyBand":"Telemetry DC","summary":"Space qualification data certifying thin-film platinum elements under deep-space thermal vacuum cycling.","keyFindings":["Zero resistance hysteresis observed after 1,000 thermal cycles between -196°C and +200°C.","Non-magnetic construction prevents magnetic field distortions in scientific space payloads."],"downloadUrl":"","visible":true}],"officialLinks":[{"title":"Thermosen Official Technology Portal","url":"https://www.thermosen.com","description":"Explore platinum RTD sensor specs, cryogenic probes, and temperature telemetry systems.","icon":"fa-temperature-half"}]},{"oemId":"tecdia","officialWebsite":"https://www.tecdia.com","portalName":"TecDia Precision Microelectronics Center","headline":"Single Layer Ceramic Capacitors, Thin-Film Substrates & Precision Diamond Tools","visible":true,"articles":[{"id":"tecdia-art-1","title":"TecDia Introduces Sub-THz Single Layer Capacitors with Self-Resonance Above 60 GHz","date":"July 2026","category":"Passive Components","readTime":"4 min read","image":"/images/gan-power-chip.jpg","summary":"Custom high-dielectric ceramics with gold wire-bondable terminations eliminate multi-layer parasitic resonances, providing ultra-clean DC bypass up to E-band.","content":"\n          <p>Traditional multi-layer ceramic capacitors (MLCC) exhibit self-resonant frequencies below 10 GHz due to internal electrode geometry. TecDia single-layer capacitors (SLC) utilize polished monolithic dielectric blocks that push parasitic resonance out past 60 GHz for mmWave MMIC biasing.</p>\n        ","tags":["Single Layer Capacitor","DC Bypass","Wire Bonding","Sub-THz"],"visible":true}],"videos":[{"id":"tecdia-vid-1","title":"Wire Bonding Techniques for Single Layer Capacitors in Microwave Modules","speaker":"TecDia Assembly Engineering Group","duration":"12:15","date":"April 2026","thumbnail":"/images/gan-power-chip.jpg","videoUrl":"","summary":"Practical tips for wedge and ball bonding gold ribbon leads to gold metallized pads without dielectric micro-cracking.","topics":["Wire Bonding","Die Attach","Assembly Best Practices"],"visible":true}],"whitepapers":[{"id":"tecdia-wp-1","title":"Optimizing MMIC Gate Biasing Networks with Ultra-High-Q Single Layer Capacitors","author":"TecDia Microelectronics Division","date":"March 2026","pages":"13 Pages","frequencyBand":"DC to 100 GHz","summary":"Analysis of ESR and ESL in single layer capacitors compared to standard surface-mount multi-layer capacitors.","keyFindings":["ESL measured under 15 picohenries across standard chip configurations.","Custom binary capacitor arrays allow in-circuit value tweaking during prototype RF tuning."],"downloadUrl":"","visible":true}],"officialLinks":[{"title":"TecDia Official Microelectronics Portal","url":"https://www.tecdia.com","description":"Single-layer capacitors, custom thin-film ceramic substrates, and precision wafer scribing tools.","icon":"fa-circle-dot"}]},{"oemId":"evans","officialWebsite":"https://www.evanscap.com","portalName":"Evans Hybrid Capacitor Lab","headline":"High-Energy-Density Tantalum Hybrid Capacitors for High-Power Pulsed Radars","visible":true,"articles":[{"id":"evans-art-1","title":"Evans Hybrid Capacitors Deliver 10x Volumetric Energy Density for Airborne Radar Pulse Discharge","date":"July 2026","category":"Energy Storage","readTime":"4 min read","image":"/images/gan-power-chip.jpg","summary":"Hermetically sealed tantalum hybrid capacitors provide hundreds of millifarads in tiny hermetic square cans, smoothing bus voltage drops during radar pulse bursts.","content":"\n          <p>Active phased array radar modules place enormous transient current demands on aircraft 28V DC bus architectures during multi-kilowatt RF pulse events. Evans Hybrid Capacitors combine an electrochemical cathode with a high-voltage tantalum anode, delivering the highest energy density of any capacitor technology available today.</p>\n        ","tags":["Hybrid Capacitor","Pulse Discharge","Tantalum","Radar Power"],"visible":true}],"videos":[{"id":"evans-vid-1","title":"Mitigating Bus Voltage Droop During 50A Radar Transmit Bursts","speaker":"Evans Capacitor Applications Team","duration":"14:30","date":"May 2026","thumbnail":"/images/gan-power-chip.jpg","videoUrl":"","summary":"Oscilloscope captures comparing bank size and voltage stability of Evans hybrid capacitors vs standard aluminum electrolytics.","topics":["Bus Droop","ESR Optimization","Pulse Power"],"visible":true}],"whitepapers":[{"id":"evans-wp-1","title":"Space-Qualified Hybrid Capacitors for Satellite Electric Propulsion and Laser Communications","author":"Evans Engineering Research","date":"February 2026","pages":"14 Pages","frequencyBand":"Pulse DC","summary":"NASA and ESA radiation tolerance and outgassing certification data for high-voltage hybrid energy storage modules.","keyFindings":["Hermetic laser-welded titanium case prevents electrolyte leakage under hard vacuum.","Over 500,000 hours MTBF documented across active defense flight programs."],"downloadUrl":"","visible":true}],"officialLinks":[{"title":"Evans Capacitor Company Official Site","url":"https://www.evanscap.com","description":"Capacitor sizing calculators, space qualification data, and high-power pulse application notes.","icon":"fa-battery-full"}]},{"oemId":"nee","officialWebsite":"https://www.nee-intl.com","portalName":"NEE Precision RF/Microwave Etching Lab","headline":"Photochemical Etching & Precision Microwave Substrates & Leadframes","visible":true,"articles":[{"id":"nee-art-1","title":"NEE International Advances Burr-Free Chemical Etching for Ultra-Thin Microwave Leadframes","date":"June 2026","category":"Precision Metal Etching","readTime":"3 min read","image":"/images/rf-microwave-pcb.jpg","summary":"Chemical machining of Kovar, copper, and beryllium-copper foils down to 12 micron thicknesses without introducing mechanical stamping stress or burrs.","content":"\n          <p>High-frequency microwave housings and hybrid microelectronic packages require leadframes and RF shielding covers with zero edge burrs to prevent dielectric short circuits. NEE International’s photochemical etching processes deliver micron-level edge straightness and tight feature tolerances.</p>\n        ","tags":["Chemical Etching","Leadframes","Kovar","Micro-Machining"],"visible":true}],"videos":[{"id":"nee-vid-1","title":"Photochemical Etching vs Laser Cutting for RF Shielding Cans","speaker":"NEE Technical Team","duration":"09:40","date":"March 2026","thumbnail":"/images/rf-microwave-pcb.jpg","videoUrl":"","summary":"Comparative metallurgical analysis examining heat-affected zones (HAZ) and surface micro-cracking in precision microwave metal components.","topics":["Photochemical Machining","Heat Affected Zone","RF Shielding"],"visible":true}],"whitepapers":[{"id":"nee-wp-1","title":"Tolerancing Precision Chemical Etched Microwave Couplers and Stepped Impedance Elements","author":"NEE International Engineering Group","date":"December 2025","pages":"8 Pages","frequencyBand":"DC to 40 GHz","summary":"Etch factor compensation rules for CAD engineers designing precision copper interdigital filters and suspended substrate stripline circuits.","keyFindings":["Feature tolerance held to ±0.012 mm on 0.1 mm thick beryllium copper.","Zero mechanical tooling costs allow rapid iteration during RF breadboarding."],"downloadUrl":"","visible":true}],"officialLinks":[{"title":"NEE International Official Site","url":"https://www.nee-intl.com","description":"Photochemical etching capabilities, material alloy selector, and metal tolerance guidelines.","icon":"fa-scissors"}]},{"oemId":"aee-isarael","officialWebsite":"https://www.aee-israel.com","portalName":"AEE Israel Perimeter Defense Systems Center","headline":"Perimeter Intrusion Detection Systems (PIDS) & Fiber-Optic Sensor Arrays","visible":true,"articles":[{"id":"aee-art-1","title":"AEE Israel Deploys Next-Gen Fiber-Optic PIDS with AI Classification of Physical Breaches","date":"May 2026","category":"Perimeter Security","readTime":"4 min read","image":"/images/rf-filter.jpg","summary":"Military-grade perimeter detection systems utilizing phase-sensitive Optical Time-Domain Reflectometry (phi-OTDR) distinguish vehicle movement from human cutting with zero false alarms.","content":"\n          <p>Critical infrastructure protection around radar installations, defense laboratories, and military perimeters requires 100% detection probability without nuisance alarms caused by wildlife or wind. AEE Israel’s integrated fiber-optic sensory perimeter provides continuous 50-kilometer boundary monitoring with location accuracy within 2 meters.</p>\n        ","tags":["PIDS","Fiber-Optic Sensing","Base Defense","Intrusion Detection"],"visible":true}],"videos":[{"id":"aee-vid-1","title":"Field Demonstration: Detecting Fence Climbing and Sub-Surface Tunneling","speaker":"AEE Defense Operations Division","duration":"11:15","date":"January 2026","thumbnail":"/images/rf-filter.jpg","videoUrl":"","summary":"Real-time telemetry showing live event detection, automated PTZ camera tracking, and military command system alerting.","topics":["OTDR Sensing","Fence Alarms","Command Integration"],"visible":true}],"whitepapers":[{"id":"aee-wp-1","title":"Eliminating Nuisance Alarms in High-Wind Environments with Deep Learning Signal Processing","author":"AEE Israel R&D Labs","date":"November 2025","pages":"12 Pages","frequencyBand":"Acoustic / Optical","summary":"Spectrogram analysis separating fence vibration patterns of mechanical wire cutting from heavy meteorological weather events.","keyFindings":["False alarm rate reduced by 99.4% in desert and coastal installations.","Zero electrical power required along the passive fiber sensor perimeter line."],"downloadUrl":"","visible":true}],"officialLinks":[{"title":"AEE Israel Official Security Portal","url":"https://www.aee-israel.com","description":"Perimeter intrusion detection systems, seismic sensors, and defense facility security hardware.","icon":"fa-shield"}]},{"oemId":"transline-technology","officialWebsite":"https://www.translinetech.com","portalName":"Transline Advanced PCB Fabrication Hub","headline":"High-Frequency RF, Microwave & Rigid-Flex PCB Manufacturing","visible":true,"articles":[{"id":"transline-art-1","title":"Transline Technology Achieves Space-Grade Certification for Mixed-Dielectric Hybrid Rigid-Flex Multilayers","date":"May 2026","category":"PCB Manufacturing","readTime":"4 min read","image":"/images/rf-microwave-pcb.jpg","summary":"Bonding high-frequency Rogers laminates with polyimide flex cores allows complex 3D avionics packaging without bulky coaxial jumper cables.","content":"\n          <p>Weight reduction and volume conservation in missile seekers and satellite payloads necessitate rigid-flex printed circuit boards. Transline Technology specializes in hybrid stackups that integrate low-loss Rogers high-frequency laminates on outer microwave layers with polyimide flex cores internally.</p>\n        ","tags":["Rigid-Flex","Hybrid Stackup","Space Qualified","Microwave PCB"],"visible":true}],"videos":[{"id":"transline-vid-1","title":"Inside the Cleanroom: Sequential Lamination of PTFE and FR-4 Hybrid Boards","speaker":"Chris Savalia, Chief Operating Officer","duration":"15:45","date":"February 2026","thumbnail":"/images/rf-microwave-pcb.jpg","videoUrl":"","summary":"A factory tour highlighting plasma desmear, automated optical inspection (AOI), and precise blind-via laser drilling for RF backplanes.","topics":["Hybrid Lamination","Plasma Desmear","Sequential Lamination"],"visible":true}],"whitepapers":[{"id":"transline-wp-1","title":"Controlling Phase Delay Variation Across Multi-Channel Phased Array Antenna Boards","author":"Transline Technology Engineering Division","date":"December 2025","pages":"14 Pages","frequencyBand":"1 to 50 GHz","summary":"Manufacturing controls on dielectric thickness tolerances and copper foil grain alignment to ensure matched electrical delay across antenna feeds.","keyFindings":["Inter-channel trace length matching held within ±0.025 mm.","Direct laser imaging (DLI) provides line width tolerances of ±0.007 mm."],"downloadUrl":"","visible":true}],"officialLinks":[{"title":"Transline Technology Official PCB Portal","url":"https://www.translinetech.com","description":"PCB design guidelines, stackup engineering assistance, and material compatibility matrices.","icon":"fa-network-wired"}]}]}'::jsonb, timezone('utc'::text, now()))
ON CONFLICT (key) DO UPDATE SET
    content = EXCLUDED.content,
    updated_at = timezone('utc'::text, now());

