VALUES ('products', '[{"id":"rogers-corporation","name":"Rogers Corporation","shortName":"Rogers","specialty":"High Frequency Laminates & Prepregs","category":"High Frequency Laminates & Prepregs","tagline":"High Performance Laminates & Prepregs for Advanced Electronics","description":"Rogers Corporation is a global leader in engineered materials for high-frequency RF, microwave, and millimeter-wave applications across defense, automotive radar, and 5G infrastructure.","website":"https://www.rogerscorp.com","logoImg":"/images/oem-logos/Rogers_Logo_no_bg.png","logoSvg":"<svg viewBox=\"0 0 200 42\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"2\" y=\"2\" width=\"38\" height=\"38\" rx=\"8\" fill=\"#CC0000\"/><path d=\"M14 11h9c4 0 6.5 2 6.5 5.2 0 2.5-1.5 4.3-4 4.9l4.8 9.9h-4.8l-4.2-9h-2.5V31H14V11zm4 7.8h4.3c1.8 0 2.8-.9 2.8-2.2 0-1.3-1-2.2-2.8-2.2H18v4.4z\" fill=\"#FFFFFF\"/><text x=\"49\" y=\"23\" fill=\"#FFFFFF\" font-family=\"''Plus Jakarta Sans'', sans-serif\" font-weight=\"900\" font-size=\"17\" letter-spacing=\"1.5\">ROGERS</text><text x=\"50\" y=\"34\" fill=\"#94A3B8\" font-family=\"''Plus Jakarta Sans'', sans-serif\" font-weight=\"700\" font-size=\"8\" letter-spacing=\"2.2\">CORPORATION</text></svg>","defaultImage":"/images/rf-laminate.jpg","accentColor":"#CC0000","glowColor":"rgba(204, 0, 0, 0.4)","visible":true,"categories":[{"id":"rt-duroid","name":"RT/Duroid","label":"","description":"PTFE composite laminate with very low dielectric constant and loss, reinforced with glass microfibers.","visible":true,"products":[{"id":"rt-duroid-5880-2","name":"RT/duroid 5880","category":"RT/Duroid","description":"PTFE composite laminate with very low dielectric constant and loss, reinforced with glass microfibers.","applications":"Antennas, RF/microwave circuits communication system, aerospace & defense, Commercial Airline Broadband Antennas, Microstrip and Stripline Circuits, Millimeter Wave Applications, Military Radar Systems, Missile Guidance Systems,